/// Registers the walkway receiver and clears the variant-1 actor script handle.
///
/// Start in state 0 with the room loaded. Borrows the room task in
/// `GAME_TASK_SLOT_ROOM`, resets the actor's published script handle only in
/// variant 1, then advances to idle state 1. It neither spawns nor kills actors.
static void _shelterB2NorthMaintenanceWalkwayInitRoomTask(Task* task)
{
    enum { SHELTER_B2_NORTH_MAINTENANCE_WALKWAY_SCRIPTED_ACTOR_VARIANT = 1 };

    task->msgTable = gShelterB2NorthMaintenanceWalkwayRoomMessages;
    gameSetTaskSlot(task, GAME_TASK_SLOT_ROOM);
    if (gGameSession->location.variant == SHELTER_B2_NORTH_MAINTENANCE_WALKWAY_SCRIPTED_ACTOR_VARIANT) {
        actor341300ResetScriptTaskHandle();
    }
    task->state = task->state + 1;
}

/// Keeps the initialized room task live to receive messages without per-frame work.
///
/// The binary reserves 16 stack bytes without accessing them.
static void _shelterB2NorthMaintenanceWalkwayIdleRoomTask(Task* unusedTask)
{
    char unusedStackSpace[0x10];
}

/// Room-controller states 0..2: initialize the receiver and actor-script handle, idle, teardown.
///
/// The controller copies all three callbacks before unchecked state dispatch.
/// No terminator; keep the room overlay loaded while the controller is live.
static const TaskFuncTable3 _gShelterB2NorthMaintenanceWalkwayStateHandlers = {
    { _shelterB2NorthMaintenanceWalkwayInitRoomTask, _shelterB2NorthMaintenanceWalkwayIdleRoomTask, taskKill },
};

void shelterB2NorthMaintenanceWalkwayRoomTask(Task* task)
{
    TaskFuncTable3 states;

    states = _gShelterB2NorthMaintenanceWalkwayStateHandlers;
    states.funcs[task->state](task);
}
